draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw an apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw a stick figure eating the apple
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 30);
  ctx.lineTo(W/2 - 50, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 10);
  ctx.lineTo(W/2 - 70, H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 10);
  ctx.lineTo(W/2 - 30, H/2 + 10);
  ctx.stroke();

  // animate the stick figure eating the apple
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50 + Math.sin(t) * 10, H/2 + 10);
  ctx.stroke();

  ctx.restore();
}
